/** Nearest point just outside the union of paths (projection on the closest edge, pushed out). */
function nearestOutside(p, paths) {
  let best = null, bd = Infinity;
  for (const poly of paths) {
    for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
      const a = poly[j], b = poly[i];
      const dx = b.X - a.X, dy = b.Y - a.Y;
      const l2 = dx * dx + dy * dy;
      let t = l2 > 0 ? ((p.X - a.X) * dx + (p.Y - a.Y) * dy) / l2 : 0;
      t = Math.max(0, Math.min(1, t));
      const qx = a.X + dx * t, qy = a.Y + dy * t;
      const d = (qx - p.X) ** 2 + (qy - p.Y) ** 2;
      if (d < bd) { bd = d; best = { X: qx, Y: qy }; }
    }
  }
  if (!best) return null;
  // push 2% of a mm further out along the move direction
  const vx = best.X - p.X, vy = best.Y - p.Y, l = Math.hypot(vx, vy) || 1;
  const q = { X: Math.round(best.X + vx / l * 0.02 * SCALE), Y: Math.round(best.Y + vy / l * 0.02 * SCALE) };
  return insidePaths(q, paths) ? null : q;
}

function insideEx(pt, ex) {
  if (!pip(pt, ex.contour)) return false;
  for (const h of ex.holes) if (pip(pt, h)) return false;
  return true;
}
function insidePaths(pt, paths) {
  let w = 0;
  for (const p of paths) if (pip(pt, p)) w += areaSign(p);
  return w > 0;
}
function areaSign(p) { let a = 0; for (let i = 0, j = p.length - 1; i < p.length; j = i++) a += (p[j].X + p[i].X) * (p[j].Y - p[i].Y); return a < 0 ? 1 : -1; }
function pip(pt, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const xi = poly[i].X, yi = poly[i].Y, xj = poly[j].X, yj = poly[j].Y;
    if ((yi > pt.Y) !== (yj > pt.Y) && pt.X < ((xj - xi) * (pt.Y - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

function samplePolygon(poly, step, cb) {
  let acc = 0;
  const n = poly.length;
  cb({ X: poly[0].X, Y: poly[0].Y });
  for (let i = 0; i < n; i++) {
    const a = poly[i], b = poly[(i + 1) % n];
    const L = Math.hypot(b.X - a.X, b.Y - a.Y);
    let t = step - acc;
    while (t < L) { cb({ X: Math.round(a.X + (b.X - a.X) * t / L), Y: Math.round(a.Y + (b.Y - a.Y) * t / L) }); t += step; }
    acc = L - (t - step);
  }
}
